        // Dynamic YouTube Video Popup Handler\n        function openPopup() {\n            var videoIframe = document.getElementById(\'ytvideo\');\n            if (videoIframe && (!videoIframe.src || videoIframe.src === \'about:blank\')) {\n                var dataSrc = videoIframe.getAttribute(\'data-src\');\n                if (dataSrc) videoIframe.src = dataSrc + \'&autoplay=1\';\n            }\n            document.getElementById(\'videoPopup\').style.display = \'flex\';\n        }\n\n        function closePopup() {\n            var videoPopup = document.getElementById(\'videoPopup\');\n            var videoIframe = document.getElementById(\'ytvideo\');\n            if (videoIframe) {\n                videoIframe.src = \'\';\n            }\n            videoPopup.style.display = \'none\';\n        }\n\n        document.getElementById(\'openPopup\').addEventListener(\'click\', function (event) {\n            event.preventDefault();\n            openPopup();\n        });\n\n        document.addEventListener(\'click\', function (event) {\n            var videoPopup = document.getElementById(\'videoPopup\');\n            if (event.target === videoPopup) {\n                closePopup();\n            }\n        });\n\n        // IntersectionObserver Lazy Loader for Google Maps Iframe\n        if (\'IntersectionObserver\' in window) {\n            var mapIframe = document.querySelector(\'.lazy-map-iframe\');\n            if (mapIframe) {\n                var mapObserver = new IntersectionObserver(function (entries) {\n                    entries.forEach(function (entry) {\n                        if (entry.isIntersecting) {\n                            var src = mapIframe.getAttribute(\'data-src\');\n                            if (src) mapIframe.src = src;\n                            mapObserver.unobserve(mapIframe);\n                        }\n                    });\n                }, { rootMargin: \'300px\' });\n                mapObserver.observe(mapIframe);\n            }\n        }\n    </script>\n\n    <!--DOWNLOAD BROCHURE CODE-->\n    <script>\n        var brochureLink = document.createElement(\'a\');\n        brochureLink.id = \'brochureLink\';\n        brochureLink.href = \'SkyMarq-e-Brochure.pdf\';\n        brochureLink.download = \'\';\n        brochureLink.style.display = \'none\';\n        document.body.appendChild(brochureLink);\n\n        var brochureForm = document.getElementById(\'download_brochre\');\n        if (brochureForm) {\n            brochureForm.addEventListener(\'submit\', function () {\n                document.getElementById(\'brochureLink\').click();\n            });\n        }\n    </script>\n\n    <!--ONLOAD POPUP TRIGGER (OPTIMIZED IDLE SHOW)-->\n    <script>\n        window.addEventListener(\'load\', function () {\n            setTimeout(function () {\n                showOnloadPopup();\n            }, 6000);\n\n            function showOnloadPopup() {\n                var isAnyInputFocused = document.querySelector(\'input:focus, textarea:focus, select:focus\');\n                if (!isAnyInputFocused) {\n                    var onloadPopupEl = document.getElementById(\'cta_onload_popup\');\n                    if (onloadPopupEl) {\n                        var onloadPopup = bootstrap.Modal.getInstance(onloadPopupEl);\n                        if (!onloadPopup) {\n                            onloadPopup = new bootstrap.Modal(onloadPopupEl);\n                        }\n                        if (!onloadPopupEl.classList.contains(\'show\')) {\n                            onloadPopup.show();\n                        }\n                    }\n                }\n            }\n        });\n    </script>\n\n    <script src="https://unpkg.com/aos@2.3.1/dist/aos.js" defer></script>\n    <script>\n        window.addEventListener(\'load\', function () {\n            if (typeof AOS !== \'undefined\' && window.innerWidth >= 768) {\n                AOS.init({\n                    offset: 50,\n          